INSERT INTO @Enrichment (code, description, seed_description, short_description, media_url, image_source_url, source_page)
VALUES
    (N'A01', N'Royal Canin Mini Adult là thức ăn hạt cho chó trưởng thành giống nhỏ từ 10 tháng tuổi. Công thức được thiết kế theo nhu cầu dinh dưỡng và mức năng lượng của chó cỡ nhỏ.', N'Thức ăn khô dành cho chó trưởng thành giống nhỏ.', N'Thức ăn khô dành cho chó trưởng thành giống nhỏ.', N'/uploads/products/cab4ecdc58065de78842bb5eb1b80609.jpg', N'https://www.petmart.vn/wp-content/uploads/2021/06/thuc-an-cho-cho-truong-thanh-co-nho-royal-canin-mini-adult1.jpg', N'https://www.petmart.vn/thuc-an-cho-cho-truong-thanh-co-nho-royal-canin-mini-adult'),
    (N'A02', N'Royal Canin Indoor 27 là thức ăn hạt cho mèo trưởng thành sống trong nhà. Trang hãng ghi sản phẩm dành cho mèo từ 1 đến 7 tuổi và có các quy cách từ gói nhỏ đến bao lớn.', N'Thức ăn khô cho mèo trưởng thành nuôi trong nhà.', N'Thức ăn khô cho mèo trưởng thành nuôi trong nhà.', N'/uploads/products/f4dfba5b139c5e6e9008ea3fa19b368c.jpg', N'https://marspetcareaprimocdn.petcare.global/6e85bfb2-2a80-4d09-800d-b3aa00a4ebfc/6e85bfb2-2a80-4d09-800d-b3aa00a4ebfc_DownloadAsJpg.jpg', N'https://www.royalcanin.com/vn/cats/products/retail-products/indoor-27-2529'),
    (N'A03', N'Whiskas Adult Tuna là thức ăn hạt vị cá ngừ dành cho mèo trưởng thành từ 1 tuổi. Sản phẩm có dạng hạt khô và được đóng gói để dùng làm bữa ăn hằng ngày.', N'Thức ăn khô vị cá ngừ dành cho mèo trưởng thành.', N'Thức ăn khô vị cá ngừ dành cho mèo trưởng thành.', N'/uploads/products/36260ab84f2855cea365c39a8bf644e8.jpg', N'https://www.whiskas.com.vn/cdn-cgi/image/width=600,height=600,f=auto,quality=90/sites/g/files/fnmzdf8261/files/2025-07/9310022866203.png', N'https://www.whiskas.com.vn/thuc-an-cho-meo-san-pham/thuc-an-kho/thuc-an-kho-whiskas-vi-ca-ngu-cho-meo-truong-thanh-tu-1-tuoi'),
    (N'A04', N'Reflex Plus Adult Cat Food with Lamb là thức ăn khô cho mèo trên 12 tháng tuổi. Theo bảng thành phần của hãng, công thức có đạm cừu, gạo, chất xơ từ củ cải đường và taurine.', N'Thức ăn khô dành cho mèo trưởng thành, công thức vị cừu.', N'Thức ăn khô dành cho mèo trưởng thành, công thức vị cừu.', N'/uploads/products/b85f06bd117f5a09b91098ec98670f39.jpg', N'https://www.reflexmama.com/upload/product_gallery/product_gallery_2025-11-13_14-04-30.png', N'https://www.reflexmama.com/reflex-plus-adult-cat-food-with-lamb'),
    (N'A05', N'Royal Canin Mini Puppy là thức ăn hạt cho chó con giống nhỏ. Công thức được thiết kế cho giai đoạn tăng trưởng của chó cỡ nhỏ.', N'Thức ăn khô dành cho chó con giống nhỏ.', N'Thức ăn khô dành cho chó con giống nhỏ.', N'/uploads/products/fa4e031dd723543098580dc9b33c2cc2.jpg', N'https://marspetcareaprimocdn.petcare.global/c2698e01-24b8-4434-b780-b2490009a85b/c2698e01-24b8-4434-b780-b2490009a85b_DownloadAsJpg.jpg', N'https://www.royalcanin.com/vn/dogs/products/retail-products/puppy---mini-3000'),
    (N'A06', N'Royal Canin Maxi Adult dành cho chó trưởng thành giống lớn từ 25 đến 44 kg và trên 15 tháng tuổi. Theo hãng, công thức sử dụng protein dễ tiêu và chất xơ cân bằng, đồng thời hỗ trợ xương khớp.', N'Thức ăn khô cho chó trưởng thành giống lớn.', N'Thức ăn khô cho chó trưởng thành giống lớn.', N'/uploads/products/132b058d90d05a6db8b31c7bceb20f99.jpg', N'https://marspetcareaprimocdn.petcare.global/174a77ba-09ae-4328-acbb-b1ef00132462/174a77ba-09ae-4328-acbb-b1ef00132462_DownloadAsJpg.jpg', N'https://www.royalcanin.com/vn/dogs/products/retail-products/maxi-adult-3007'),
    (N'A07', N'Royal Canin Kitten là thức ăn hạt cho mèo con trong giai đoạn tăng trưởng. Công thức được phát triển cho nhu cầu dinh dưỡng của mèo con trước khi chuyển sang thức ăn cho mèo trưởng thành.', N'Thức ăn khô dành cho mèo con trong giai đoạn tăng trưởng.', N'Thức ăn khô dành cho mèo con trong giai đoạn tăng trưởng.', N'/uploads/products/7d66bbf2395a5874a92116f27308f88b.jpg', N'https://marspetcareaprimocdn.petcare.global/fa1241ac-7528-4e00-b045-b2490009a695/fa1241ac-7528-4e00-b045-b2490009a695_DownloadAsJpg.jpg', N'https://www.royalcanin.com/vn/cats/products/retail-products/kitten-2522'),
    (N'A08', N'Royal Canin Sterilised 37 là thức ăn hạt cân bằng dành cho mèo đã triệt sản từ 1 đến 7 tuổi. Sản phẩm thuộc dòng dinh dưỡng hằng ngày cho mèo trưởng thành.', N'Thức ăn khô dành cho mèo trưởng thành đã triệt sản.', N'Thức ăn khô dành cho mèo trưởng thành đã triệt sản.', N'/uploads/products/d99b12a7e28555299d0cdb12500f5a3f.jpg', N'https://cdn.royalcanin-weshare-online.io/SCEua2QBaxEApS7Lk_vW/v176/16-sterilised-37-b1-ru', N'https://www.royalcanin.com/vn/cats/products/retail-products/sterilised-37-2537'),
    (N'B01', N'KONG Classic làm từ cao su tự nhiên màu đỏ, có khoang để nhét bánh thưởng hoặc thức ăn. Thiết kế nảy không đều phù hợp trò chơi nhai và tương tác với chó.', N'Đồ chơi cao su tự nhiên, có khoang nhét thức ăn và độ nảy linh hoạt.', N'Đồ chơi cao su tự nhiên, có khoang nhét thức ăn và độ nảy linh hoạt.', N'/uploads/products/d77610b4708d5831b522e2d577119acd.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/2003/images/17372/d6942459-9ca0-4890-a0e2-d3e723874e63_medium__34276.1793893580.386.513.jpg?c=1', N'https://www.kongcompany.com/kong-classic/'),
    (N'B02', N'KONG Extreme là đồ chơi cao su màu đen dành cho chó nhai mạnh. Bên trong có khoang nhét thức ăn để tăng thời gian chơi tương tác.', N'Đồ chơi cao su dành cho chó có thói quen nhai mạnh.', N'Đồ chơi cao su dành cho chó có thói quen nhai mạnh.', N'/uploads/products/c4ba93e87ad85bf29d716947c5e20372.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/2000/images/15239/cccae0aa-2144-4383-ab38-6d07932ad5ba_medium__46782.1793893766.386.513.jpg?c=1', N'https://www.kongcompany.com/kong-extreme/'),
    (N'B03', N'KONG SqueakAir kết hợp bóng ném nhặt và tiếng kêu. Sản phẩm dành cho trò chơi ném bóng cùng chó; cần chọn đúng cỡ và số bóng trong gói khi mua.', N'Bóng đồ chơi kết hợp âm thanh để chơi ném và nhặt.', N'Bóng đồ chơi kết hợp âm thanh để chơi ném và nhặt.', N'/uploads/products/0f7c6be132905ad0aa8ae53ac0353c77.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/1949/images/14786/d49c96d1-360e-4cac-bede-fe366eae68ad_medium__45898.1793892967.386.513.jpg?c=1', N'https://www.kongcompany.com/squeakair-balls/'),
    (N'B04', N'KONG Wild Knots Bear có lớp ngoài mềm và kết cấu dây thắt nút ở bên trong. Đây là đồ chơi hình gấu dành cho chó thích ôm và tương tác.', N'Đồ chơi hình gấu có dây thừng thắt nút bên trong.', N'Đồ chơi hình gấu có dây thừng thắt nút bên trong.', N'/uploads/products/40fe200b6d7f5475ad7a999958dd597c.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/1973/images/14979/45deae39-0d1c-4e96-b74e-f669fc250807_w_450%2526h_450%2526f_jpg%2526q_95__85117.1793893344.386.513.jpg?c=1', N'https://www.kongcompany.com/wild-knots-bear/'),
    (N'B05', N'KONG Wubba có các dải vải dài để chó dễ ngậm, lắc và kéo. Có thể dùng trong trò ném nhặt hoặc chơi tương tác với người nuôi.', N'Đồ chơi có các dải vải dài phù hợp trò ném và kéo.', N'Đồ chơi có các dải vải dài phù hợp trò ném và kéo.', N'/uploads/products/9ecdc1b31e135c3c8e272e5b8705d657.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/1977/images/15022/744d4fbf-17cb-4758-baf4-1fff15b1ccd5_medium__80897.1793893360.386.513.jpg?c=1', N'https://www.kongcompany.com/wubba/'),
    (N'B06', N'KONG Tugga Wubba kết hợp phần thân bọc vải và dây bện để chơi kéo co. Hai đầu đồ chơi giúp chó dễ ngậm và lắc khi chơi.', N'Đồ chơi có dây bện phù hợp tương tác kéo co.', N'Đồ chơi có dây bện phù hợp tương tác kéo co.', N'/uploads/products/5a962b9fc4375d6aa5f7bd62b626f9cf.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/2012/images/15459/4b9a25b5-0c98-4075-99cf-9d036dca6339_medium__71179.1793893818.386.513.jpg?c=1', N'https://www.kongcompany.com/tugga-wubba/'),
    (N'B07', N'KONG Wubba Sport Basketball có phần đầu hình bóng rổ và dải vải dài. Thiết kế phù hợp trò ném nhặt và kéo tương tác với chó.', N'Đồ chơi hình bóng rổ với dải vải để ném và kéo.', N'Đồ chơi hình bóng rổ với dải vải để ném và kéo.', N'/uploads/products/d22fb3629fd85043b990411add996862.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/2280/images/18294/3514ffde-e7c2-4c00-b0a0-8f68b981023a_medium__78618.1793894539.386.513.jpg?c=1', N'https://www.kongcompany.com/wubba-sport-basketball/'),
    (N'B08', N'KONG Wubba Sport Soccer Ball có phần đầu hình bóng đá, dải vải dài và tiếng kêu. Vải được gia cố để phục vụ trò ném nhặt và kéo.', N'Đồ chơi hình bóng đá có dải vải dài.', N'Đồ chơi hình bóng đá có dải vải dài.', N'/uploads/products/4c3fdd4b2c85550f9f9a949da408f5db.jpg', N'https://cdn11.bigcommerce.com/s-k3kxaf4rop/products/2338/images/18760/1c0eae98-dc72-4365-ac01-3ae11a6ddca3_medium__94639.1793894543.386.513.jpg?c=1', N'https://www.kongcompany.com/wubba-sport-soccer-ball/'),
    (N'C01', N'FURminator Small Cat Short Hair là lược lấy lông tơ cho mèo nhỏ lông ngắn. Lưỡi chải bằng thép không gỉ và nút FURejector giúp lấy phần lông đã gom khỏi lược.', N'Lược chăm sóc bộ lông dành cho mèo lông ngắn.', N'Lược chăm sóc bộ lông dành cho mèo lông ngắn.', N'/uploads/products/900ab1ff0e2d52b0915797705fee156e.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/new-product-images/p929173_gallery_01_hero_lores.jpg?rev=c0caf4eaad104b66ab1d6aa05c845328', N'https://www.furminator.com/products/tools/deshedding-tools/undercoat-deshedding-tool-small-cat-short-hair'),
    (N'C02', N'FURminator Medium Dog Long Hair là lược lấy lông tơ dành cho chó cỡ vừa lông dài. Đầu chải giúp lấy lông rụng dưới lớp lông ngoài khi sử dụng đúng hướng dẫn.', N'Lược chăm sóc bộ lông cho chó lông dài.', N'Lược chăm sóc bộ lông cho chó lông dài.', N'/uploads/products/fa412ef9806654cc85b6fd863e7d619d.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/new-product-images/p92914_galleryimages_01_hero.jpg?rev=183f2905558848d69fba3c9e724330b6', N'https://www.furminator.com/products/tools/deshedding-tools/undercoat-deshedding-tool-medium-dog-long-hair'),
    (N'C03', N'Kem đánh răng Virbac C.E.T. dùng cho chó và mèo, với hệ enzyme hỗ trợ vệ sinh răng miệng. Sản phẩm được dùng cùng bàn chải thú cưng; quy cách tham khảo là tuýp 70 g.', N'Kem đánh răng thú cưng chứa enzyme dùng trong chăm sóc răng miệng.', N'Kem đánh răng thú cưng chứa enzyme dùng trong chăm sóc răng miệng.', N'/uploads/products/52c80d4d07055d8994b0c171a36f27da.jpg', N'https://uk.virbac.com/var/site/storage/images/4/8/9/2/22984-1-eng-GB/f24ba0b83054-309623_Packshot_Enzymatic-Toothpaste_70g_face.png', N'https://uk.virbac.com/products/enzymatic-toothpaste-for-dogs-cats?category=128'),
    (N'C04', N'Kềm cắt móng FURminator có lưỡi cắt bằng thép không gỉ và tay cầm dễ nắm. Sản phẩm dùng để chăm sóc móng cho chó và mèo.', N'Kềm cắt móng có lưỡi thép không gỉ và tay cầm dễ nắm.', N'Kềm cắt móng có lưỡi thép không gỉ và tay cầm dễ nắm.', N'/uploads/products/1c916a8c4e335290a83ea3c2a0c163d3.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/new-product-images/p104014_gallery_01_front.jpg?rev=24420ab9cfae462da22a9d0cea758296', N'https://www.furminator.com/products/tools/nail-care/nail-clippers'),
    (N'C05', N'FURminator Bathing Brush là bàn chải dùng trong lúc tắm cho thú cưng. Thiết kế cho phép chứa và phân phối dầu tắm hoặc dầu xả khi chải qua bộ lông.', N'Bàn chải hỗ trợ chăm sóc lông trong lúc tắm.', N'Bàn chải hỗ trợ chăm sóc lông trong lúc tắm.', N'/uploads/products/55267123225159cea901abb137381ad7.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/bathe/p92932/p92932_galleryimages_01_front.jpg?rev=c4ee15bc41be41d895418eb492afb78e', N'https://www.furminator.com/products/coat-care/shampoos-and-conditioners/bathing-brush'),
    (N'C06', N'FURminator Nail Grinder là dụng cụ mài và làm nhẵn móng cho chó mèo. Sản phẩm dùng trong bước chăm sóc móng sau khi kiểm tra độ dài móng phù hợp.', N'Dụng cụ mài móng dành cho thú cưng.', N'Dụng cụ mài móng dành cho thú cưng.', N'/uploads/products/e3338edc87325a6aa03fd55ca9d61545.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/new-product-images/p104005_nailgrinder_gallery_01_front.jpg?rev=d600b974fa7342c79dba6f39b1df71e4', N'https://www.furminator.com/products/tools/nail-care/nail-grinder'),
    (N'C07', N'Bàn chải răng Virbac C.E.T. Dual-Ended có hai đầu chải cho vùng răng khác nhau. Sản phẩm dùng cho việc vệ sinh răng miệng thường xuyên của chó và mèo.', N'Bàn chải răng hai đầu để chăm sóc răng miệng thú cưng.', N'Bàn chải răng hai đầu để chăm sóc răng miệng thú cưng.', N'/uploads/products/5b38d1b4f63253d8977d8ab8ca1fbaf2.jpg', N'https://us.virbac.com/files/live/sites/virbac-usa/files/predefined-files/product/CET_Dual_Ended_Toothbrush_B.jpg', N'https://us.virbac.com/home/our-products/pagecontent/product-selector/cet-brand-toothbrushes.html'),
    (N'C08', N'FURminator Dual Grooming Brush có hai mặt chải trong cùng một dụng cụ. Sản phẩm dùng để chải và làm mượt bộ lông thú cưng.', N'Bàn chải hai mặt để chải và làm mượt lông.', N'Bàn chải hai mặt để chải và làm mượt lông.', N'/uploads/products/b6afe8efadf15267bf1003ddc187dd19.jpg', N'https://sc10cdn.spectrumbrands.com/-/media/project/spectrumcommerce/furminator/images/product-images/brush/dual-grooming-brush/p92929_fur_dualsidedbrush_g01_front.jpg?rev=cec22f2cc9b44c0eb08d7788b3771bd0', N'https://www.furminator.com/products/brush/brushes-and-rakes/dual-grooming-brush'),
